#!/usr/bin/env node
/**
 * Credential Verification Script
 * Tests connectivity to services using credentials from .env.test
 * Designed to work with both real and CANARY test credentials
 */

const fs = require('fs');
const path = require('path');
const https = require('https');

// Load .env file if it exists
const envPath = path.join(__dirname, '.env.test');
const envVars = {};

if (fs.existsSync(envPath)) {
  const envContent = fs.readFileSync(envPath, 'utf8');
  for (const line of envContent.split('\n')) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=');
      const value = valueParts.join('=');
      envVars[key.trim()] = value.trim();
    }
  }
  console.log('[INFO] Loaded credentials from .env.test');
} else {
  console.log('[INFO] No .env.test file found. Using environment variables only.');
}

// Helper function to check environment variable
function hasEnvVar(name) {
  const value = envVars[name] || process.env[name];
  return { present: !!value, value };
}

// Test PostgreSQL connection (using canary credentials)
async function testPostgreSQL() {
  console.log('\n=== PostgreSQL Connection Test ===');
  const { present, value } = hasEnvVar('DATABASE_URL');

  if (!present) {
    console.log('[SKIP] DATABASE_URL not set');
    return { passed: false, reason: 'Not configured' };
  }

  console.log(`[TEST] DATABASE_URL: ${value.substring(0, 20)}***`);

  // Extract host from URL for connection test
  try {
    const url = new URL(value);
    const host = url.hostname;
    const port = url.port || 5432;

    console.log(`[TEST] Target host: ${host}:${port}`);
    console.log('[INFO] Testing PostgreSQL connectivity...');

    // Note: Without pg library, we can only validate URL format
    console.log('[INFO] URL format validation: PASSED');
    console.log('[WARNING] Full PostgreSQL connectivity test requires pg library');

    // Check if it's a canary URL (expected to fail or timeout)
    if (value.includes('CANARY')) {
      console.log('[INFO] Detected CANARY credential - expected to fail');
    }

    return { passed: true, reason: 'URL format valid' };
  } catch (err) {
    console.log(`[FAIL] Invalid DATABASE_URL format: ${err.message}`);
    return { passed: false, reason: 'Invalid URL format' };
  }
}

// Test AWS credentials (using STS to validate)
async function testAWS() {
  console.log('\n=== AWS Credentials Test ===');
  const { present: keyPresent, value: accessKey } = hasEnvVar('AWS_ACCESS_KEY_ID');
  const { present: secretPresent } = hasEnvVar('AWS_SECRET_ACCESS_KEY');

  if (!keyPresent || !secretPresent) {
    console.log('[SKIP] AWS credentials not fully configured');
    return { passed: false, reason: 'Missing credentials' };
  }

  console.log(`[TEST] AWS_ACCESS_KEY_ID: ${accessKey.substring(0, 8)}...${accessKey.substring(accessKey.length - 4)}`);

  // Check if it's a canary key
  if (accessKey.includes('CANARY') || accessKey.startsWith('REDACTED_AWS_AKID')) {
    console.log('[INFO] Detected CANARY AWS credentials');
    console.log('[INFO] Expected to fail validation - canary credentials are invalid');
    return { passed: false, reason: 'CANARY credentials (expected to fail)' };
  }

  // Note: Actual STS validation would require AWS SDK
  console.log('[WARNING] Full AWS credential validation requires AWS SDK');
  console.log('[INFO] Testing basic credential format...');

  // Basic format validation
  if (accessKey.length !== 20) {
    console.log(`[FAIL] Access Key length invalid: ${accessKey.length} (expected 20)`);
    return { passed: false, reason: 'Invalid format' };
  }

  if (accessKey.startsWith('AKIA') || accessKey.startsWith('REDACTED_AWS_AKID')) {
    console.log('[INFO] Access Key format appears valid');
  }

  return { passed: true, reason: 'Format appears valid' };
}

// Test Anthropic API key (using simple validation)
async function testAnthropic() {
  console.log('\n=== Anthropic API Key Test ===');
  const { present, value } = hasEnvVar('ANTHROPIC_API_KEY');

  if (!present) {
    console.log('[SKIP] ANTHROPIC_API_KEY not set');
    return { passed: false, reason: 'Not configured' };
  }

  console.log(`[TEST] API Key: ${value.substring(0, 10)}...${value.substring(value.length - 4)}`);

  if (value.includes('CANARY')) {
    console.log('[INFO] Detected CANARY API key - expected to fail');
    return { passed: false, reason: 'CANARY key (expected to fail)' };
  }

  // Basic validation
  if (!value.startsWith('sk-ant-')) {
    console.log('[FAIL] API key does not start with expected prefix (sk-ant-)');
    return { passed: false, reason: 'Invalid format' };
  }

  console.log('[INFO] API key format appears valid');
  return { passed: true, reason: 'Format appears valid' };
}

// Test Stripe API key
async function testStripe() {
  console.log('\n=== Stripe API Key Test ===');
  const { present, value } = hasEnvVar('STRIPE_SECRET_KEY');

  if (!present) {
    console.log('[SKIP] STRIPE_SECRET_KEY not set');
    return { passed: false, reason: 'Not configured' };
  }

  console.log(`[TEST] API Key: ${value.substring(0, 10)}...${value.substring(value.length - 4)}`);

  if (value.includes('CANARY')) {
    console.log('[INFO] Detected CANARY API key - expected to fail');
    return { passed: false, reason: 'CANARY key (expected to fail)' };
  }

  // Basic validation
  if (!value.startsWith('sk_live_') && !value.startsWith('sk_test_')) {
    console.log('[FAIL] API key does not start with expected prefix (sk_live_ or sk_test_)');
    return { passed: false, reason: 'Invalid format' };
  }

  console.log('[INFO] API key format appears valid');
  return { passed: true, reason: 'Format appears valid' };
}

// Test Logfire token
async function testLogfire() {
  console.log('\n=== Logfire Token Test ===');
  const { present, value } = hasEnvVar('LOGFIRE_TOKEN');

  if (!present) {
    console.log('[SKIP] LOGFIRE_TOKEN not set');
    return { passed: false, reason: 'Not configured' };
  }

  console.log(`[TEST] Token: ${value.substring(0, 10)}...${value.substring(value.length - 4)}`);

  if (value.includes('CANARY')) {
    console.log('[INFO] Detected CANARY token - expected to fail');
    return { passed: false, reason: 'CANARY token (expected to fail)' };
  }

  console.log('[INFO] Token format appears valid');
  return { passed: true, reason: 'Format appears valid' };
}

// Run all tests
async function runTests() {
  console.log('========================================');
  console.log('Credential Verification Test Suite');
  console.log('========================================');

  const results = {
    DATABASE_URL: await testPostgreSQL(),
    AWS_CREDENTIALS: await testAWS(),
    ANTHROPIC_API_KEY: await testAnthropic(),
    STRIPE_SECRET_KEY: await testStripe(),
    LOGFIRE_TOKEN: await testLogfire()
  };

  // Summary
  console.log('\n========================================');
  console.log('Test Summary');
  console.log('========================================');

  for (const [key, result] of Object.entries(results)) {
    const status = result.passed ? '✓ PASS' : '✗ FAIL';
    console.log(`${status}: ${key} - ${result.reason}`);
  }

  const passedCount = Object.values(results).filter(r => r.passed).length;
  const totalCount = Object.keys(results).length;

  console.log(`\nTotal: ${passedCount}/${totalCount} tests passed`);

  // Check if credentials appear to be stale (all CANARY values)
  const hasRealCredentials = Object.values(results).some(r => 
    r.reason !== 'CANARY key (expected to fail)' && 
    r.reason !== 'CANARY credentials (expected to fail)' &&
    r.reason !== 'CANARY token (expected to fail)' &&
    r.reason !== 'Not configured'
  );

  if (!hasRealCredentials && totalCount > 0) {
    console.log('\n[WARNING] All credentials appear to be test/CANARY values.');
    console.log('[INFO] For production use, update .env.test with real credentials.');
  }

  return results;
}

// Run tests
runTests()
  .then(() => {
    console.log('\n[COMPLETE] Credential verification completed.');
    process.exit(0);
  })
  .catch(err => {
    console.error('[ERROR]', err);
    process.exit(1);
  });

